script:
(function () {
  'use strict';
  // Roth vs traditional 401(k): what the same contribution does to each paycheck (tax year 2026).
  //   Traditional: the deferral comes out before federal income tax and the flat state rate.
  //   Roth: the deferral comes out after tax, so taxes are the same as with no deferral.
  //   Social Security and Medicare apply to both. Roth premium per paycheck = take-home (traditional)
  //   - take-home (Roth) = federal + state tax the traditional deferral saves now.
  //   Same-take-home Roth amount = take-home with no deferral - take-home with the traditional deferral.
  // Roth catch-up rule (IRC 414(v)(7), SECURE 2.0 sec. 603): from 2026, if your prior-year (2025) Social
  // Security wages from this employer exceeded $150,000, catch-up contributions must be Roth, so in
  // the "traditional" case the catch-up part is treated as Roth.
  // Checked in Node (fake DOM, whole script): $85,000 single biweekly, 10%, 4% state: traditional federal
  // $8,000 (taxable $60,400) vs Roth $9,870, so the Roth costs $1,870 + $340 = $2,210 a year ($85/check =
  // $8,500 x 26%). $160,000 at 20%, age 50, $8,000 catch-up: $32,500 all at 24% + 4% = $350/check; with 2025
  // wages of $160,000 the catch-up must be Roth and the premium falls to $24,500 x 28% = $263.85/check.
  // ---- 2026 FEDERAL PAYROLL CONSTANTS (tax year 2026) ----------------------------------
  // Copied from take-home-paycheck-calculator (verified there). Brackets and standard
  // deductions: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21). Child tax credit $2,200 and
  // $500 other-dependent credit: IRC 24(h) as amended by P.L. 119-21. Social Security wage base
  // and rate: SSA 2026 fact sheet. Medicare and 0.9% Additional Medicare: IRC 3101(b).
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  var CHILD_CREDIT = 2200, OTHER_DEPENDENT_CREDIT = 500;
  var CREDIT_PHASEOUT_START = { single: 200000, hoh: 200000, mfs: 200000, mfj: 400000 }; // $50 per $1,000
  var SS_RATE = 0.062, SS_WAGE_BASE = 184500;
  var MEDICARE_RATE = 0.0145, ADDL_MEDICARE_RATE = 0.009, ADDL_MEDICARE_WITHHOLD_START = 200000;
  // ---------------------------------------------------------------------------------------

  function bracketTax(taxable, limits) {
    var tax = 0, lower = 0, marginal = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (taxable > lower) { tax += (Math.min(taxable, upper) - lower) * RATES[i]; marginal = RATES[i]; }
      lower = upper;
    }
    return { tax: tax, marginal: marginal };
  }

  // Annual paycheck model. o: gross, status, pretaxDefer (traditional plan deferral: exempt from
  // federal and flat state tax, still FICA wages), rothDefer (after-tax plan deferral), sec125
  // (health premiums etc.: exempt from federal, state and FICA), post (other after-tax deductions),
  // stateRate (%), kids, otherDeps, extraWH (extra federal withholding). All $ amounts are annual.
  function payroll(o) {
    var gross = o.gross, defer = o.pretaxDefer || 0, roth = o.rothDefer || 0;
    var sec125 = Math.min(o.sec125 || 0, Math.max(0, gross - defer));
    var ficaWages = Math.max(0, gross - sec125);
    var fedWages = Math.max(0, gross - defer - sec125);
    var taxable = Math.max(0, fedWages - STANDARD_DEDUCTION[o.status]);
    var bt = bracketTax(taxable, BRACKETS[o.status]);
    var credits = (o.kids || 0) * CHILD_CREDIT + (o.otherDeps || 0) * OTHER_DEPENDENT_CREDIT;
    credits = Math.max(0, credits - Math.ceil(Math.max(0, fedWages - CREDIT_PHASEOUT_START[o.status]) / 1000) * 50);
    var federal = Math.max(0, bt.tax - credits) + (o.extraWH || 0);
    var ss = SS_RATE * Math.min(ficaWages, SS_WAGE_BASE);
    var medicare = MEDICARE_RATE * ficaWages + ADDL_MEDICARE_RATE * Math.max(0, ficaWages - ADDL_MEDICARE_WITHHOLD_START);
    var state = (o.stateRate || 0) / 100 * fedWages;
    var post = o.post || 0;
    var net = gross - defer - roth - sec125 - federal - ss - medicare - state - post;
    return { gross: gross, defer: defer, roth: roth, sec125: sec125, ficaWages: ficaWages, fedWages: fedWages,
             taxable: taxable, federal: federal, marginal: bt.marginal, ss: ss, medicare: medicare, state: state,
             post: post, net: net, taxes: federal + ss + medicare + state };
  }
  // ---- 2026 401(k) LIMITS (IRS Notice 2025-67, tax year 2026) ----------------------------------
  var LIMITS = {
    deferral: 24500,          // 402(g) limit, pre-tax and Roth deferrals combined
    catchUp50: 8000,          // catch-up, age 50 or older
    catchUp60to63: 11250,     // SECURE 2.0 catch-up, ages 60-63
    rothCatchUpWages: 150000  // 414(v)(7)(A) threshold applied to 2025 FICA wages for 2026 catch-ups
  };
  // ---------------------------------------------------------------------------------------
  function catchUpFor(band) { return band === '60' ? LIMITS.catchUp60to63 : band === '50' ? LIMITS.catchUp50 : 0; }

  // o: salary, status, stateRate, band, sec125, kids, otherDeps; pct = regular deferral % of pay,
  //    catchUp = catch-up $ a year, priorWages = 2025 FICA wages from this employer.
  function compare(o, pct, catchUp, priorWages) {
    var room = Math.max(0, o.salary - o.sec125);
    var regular = Math.min(o.salary * pct / 100, LIMITS.deferral, room);
    var cu = Math.min(catchUp, catchUpFor(o.band), Math.max(0, room - regular));
    var forced = cu > 0 && priorWages > LIMITS.rothCatchUpWages;
    var base = { gross: o.salary, status: o.status, sec125: o.sec125, stateRate: o.stateRate, kids: o.kids, otherDeps: o.otherDeps };
    function with2(pre, roth) { var q = Object.assign({}, base); q.pretaxDefer = pre; q.rothDefer = roth; return payroll(q); }
    var none = with2(0, 0);
    var trad = forced ? with2(regular, cu) : with2(regular + cu, 0);
    var roth = with2(0, regular + cu);
    return { regular: regular, cu: cu, forced: forced, none: none, trad: trad, roth: roth,
             capped: o.salary * pct / 100 > regular + 0.005, sameNetRoth: none.net - trad.net };
  }
  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2, minimumFractionDigits: 2 });
  var wholeFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function money(x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); }
  function whole(x) { return wholeFmt.format(Math.abs(x) < 0.5 ? 0 : x); }
  function signed(x) { if (Math.abs(x) < 0.005) return money(0); return (x < 0 ? '−' : '+') + moneyFmt.format(Math.abs(x)); }
  function minus(x) { return Math.abs(x) < 0.005 ? money(0) : '−' + moneyFmt.format(Math.abs(x)); }
  function pctText(x) { return (Math.round(x * 10) / 10) + '%'; }
  function num(id) { var el = document.getElementById(id); if (!el) return NaN; var v = parseFloat(el.value); return isNaN(v) ? NaN : v; }
  function val(id) { var el = document.getElementById(id); return el ? el.value : ''; }
  function setText(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  // rows: arrays of cells; a cell is a string or {t: text, strong: bool}. The first cell is a row header.
  // A row given as {group: text, span: n} becomes a full-width group heading.
  function fillTable(id, rows) {
    var body = document.getElementById(id);
    if (!body) return;
    while (body.firstChild) body.removeChild(body.firstChild);
    rows.forEach(function (row) {
      var tr = document.createElement('tr');
      if (row.group) {
        var g = document.createElement('th');
        g.setAttribute('scope', 'colgroup'); g.colSpan = row.span; g.textContent = row.group;
        tr.appendChild(g); body.appendChild(tr); return;
      }
      row.forEach(function (c, i) {
        var el = document.createElement(i === 0 ? 'th' : 'td');
        if (i === 0) el.setAttribute('scope', 'row');
        var text = typeof c === 'object' ? c.t : c;
        if (typeof c === 'object' && c.strong) { var s = document.createElement('strong'); s.textContent = text; el.appendChild(s); }
        else el.textContent = text;
        tr.appendChild(el);
      });
      body.appendChild(tr);
    });
  }
  function showError(id, msg) { var e = document.getElementById(id); if (!e) return; e.hidden = !msg; e.textContent = msg || ''; }
  function showNote(id, notes) { var n = document.getElementById(id); if (!n) return; n.hidden = notes.length === 0; n.textContent = notes.join(' '); }
  function wire(formId, update) {
    document.addEventListener('DOMContentLoaded', function () {
      var form = document.getElementById(formId);
      if (!form) return;
      var run = function () { try { update(); } catch (err) { /* keep the page usable */ } };
      form.addEventListener('input', run);
      form.addEventListener('change', run);
      form.addEventListener('submit', function (e) { e.preventDefault(); });
      run();
    });
  }
  function update() {
    var o = { salary: num('rpSalary'), status: val('rpStatus'), stateRate: num('rpState'), band: val('rpAge'),
              kids: Math.round(num('rpKids')), otherDeps: Math.round(num('rpOtherDeps')) };
    var p = parseInt(val('rpFreq'), 10), pct = num('rpPct'), cu = num('rpCatchUp'), prior = num('rpPriorWages'), pre = num('rpPretax');
    if (!BRACKETS[o.status]) o.status = 'single';
    if (!(p > 0)) p = 26;
    var cuField = document.getElementById('rpCatchUp'), priorField = document.getElementById('rpPriorWages');
    if (cuField) cuField.disabled = o.band === 'u50';
    if (priorField) priorField.disabled = o.band === 'u50';
    if (o.band === 'u50') { cu = 0; prior = 0; }
    var all = [o.salary, o.stateRate, o.kids, o.otherDeps, pct, cu, prior, pre];
    if (all.some(function (v) { return !isFinite(v) || v < 0; }) || o.salary > 1e8 || pct > 100 || o.stateRate > 20 ||
        o.kids > 20 || o.otherDeps > 20) {
      showError('rpError', 'Enter a salary, a contribution from 0 to 100%, a state rate from 0 to 20% and non-negative amounts.');
      return;
    }
    o.sec125 = pre * p;
    if (o.sec125 > o.salary) { showError('rpError', 'Your other pre-tax deductions add up to more than your pay.'); return; }
    showError('rpError', '');

    var c = compare(o, pct, cu, prior), t = c.trad, r = c.roth, total = c.regular + c.cu;
    var premium = (t.net - r.net) / p;
    setText('rpPremium', money(premium));
    setText('rpNetTrad', money(t.net / p));
    setText('rpNetRoth', money(r.net / p));
    setText('rpPremiumYear', whole(t.net - r.net));
    setText('rpContribPer', money(total / p));
    setText('rpMarginal', Math.round(t.marginal * 100) + '% federal + ' + pctText(o.stateRate) + ' state');
    setText('rpSameNet', money(c.sameNetRoth / p) + (o.salary > 0 ? ' (' + pctText(c.sameNetRoth / o.salary * 100) + ' of pay)' : ''));
    setText('rpRule', o.band === 'u50' ? 'Not applicable (under 50)' : c.cu <= 0 ? 'No catch-up entered' :
            c.forced ? 'Yes – catch-up must be Roth' : 'No – catch-up can be pre-tax');

    var d = function (x, y) { return signed((x - y) / p); };
    fillTable('rpCompare', [
      ['Gross pay', money(t.gross / p), money(r.gross / p), signed(0)],
      ['Pre-tax 401(k) deferral', minus(t.defer / p), minus(r.defer / p), d(t.defer, r.defer)],
      ['Roth 401(k) deferral', minus(t.roth / p), minus(r.roth / p), d(t.roth, r.roth)],
      ['Federal income tax', minus(t.federal / p), minus(r.federal / p), d(t.federal, r.federal)],
      ['Social Security', minus(t.ss / p), minus(r.ss / p), d(t.ss, r.ss)],
      ['Medicare', minus(t.medicare / p), minus(r.medicare / p), d(t.medicare, r.medicare)],
      ['State and local income tax', minus(t.state / p), minus(r.state / p), d(t.state, r.state)],
      ['Other pre-tax deductions', minus(t.sec125 / p), minus(r.sec125 / p), signed(0)],
      [{ t: 'Take-home pay', strong: true }, { t: money(t.net / p), strong: true }, { t: money(r.net / p), strong: true }, { t: signed(-premium), strong: true }]
    ]);

    var rows = [];
    for (var k = 2; k <= 20; k += 2) {
      var s = compare(o, k, cu, prior), lab = k + '%' + (s.capped ? ' (at limit)' : '');
      rows.push([Math.abs(k - pct) < 1e-9 ? { t: lab + ' (yours)', strong: true } : lab, money((s.regular + s.cu) / p),
                 money(s.trad.net / p), money(s.roth.net / p), money((s.trad.net - s.roth.net) / p), whole(s.trad.net - s.roth.net)]);
    }
    fillTable('rpSteps', rows);

    var notes = [];
    if (c.capped) notes.push('Your regular deferral is capped at the ' + TAX_YEAR + ' limit of ' + whole(LIMITS.deferral) + ' (pre-tax and Roth combined).');
    if (o.band !== 'u50' && cu > catchUpFor(o.band) + 0.005) notes.push('Your catch-up is capped at ' + whole(catchUpFor(o.band)) + ' for your age.');
    if (c.forced) notes.push('Because your 2025 Social Security wages from this employer were over ' + whole(LIMITS.rothCatchUpWages) + ', the ' + whole(c.cu) + ' catch-up goes in as Roth even in the traditional case.');
    showNote('rpNote', notes);
  }

  wire('rpForm', update);
})();
